/* ============================================================
   segment/04_candidate_segment_parents.sql (seed, parents candidate 정의+세그먼트
   피처 추출 통합 쿼리 — pipeline/generate_seed_queries.py candidate 명령으로 자동 생성)

   PARAMETERS
     SEED_NAME       = parents
     PERIOD          = 2026-06-01 ~ 2026-09-25 (같은 연도 내에서만 지원, 시작일은
                        항상 시작월 1일부터로 가정 — 다르면 수동으로 고칠 것)
     EXCLUDED_SEEDS  = seed_piellaven_ad_id, seed_discharged_male_ad_id, seed_enlistee_ad_id, seed_gomsin_ad_id, seed_je_ad_id, seed_parents_ad_id, seed_shoplinker_ad_id
                        (seed/queries/02_create_seed_ad_id_table*.sql 전체를 스캔해 자동
                        도출 — 새 seed가 생기면 다음 생성 때 자동으로 포함된다)
     FILTERS         = region=KR, OS=Android(device_osv 숫자), skp 세그먼트 보유,
                        컴플라이언스(collect=1, lmt!=1), device_ifa UUID 형식

   CREATE TABLE 없이 SELECT 하나로 candidate 정의와 세그먼트 피처 추출을 동시에 한다
   (03_create_candidate_table.sql + 04_candidate_segment.sql을 합친 버전 — 그 두 파일은
   이미 실행된 seed의 provenance 기록이라 건드리지 않고 그대로 둔다). ID 목록/taxonomy는
   02_seed_segment_je.sql과 동일 — taxonomy가 바뀌면 전부 같이 갱신할 것.
   ============================================================ */

WITH segments_latest AS (
    SELECT
        ad_id AS device_ifa,
        CAST(segments AS VARCHAR) AS segments,
        ROW_NUMBER() OVER (
            PARTITION BY ad_id
            ORDER BY year DESC, month DESC, day DESC
        ) AS rn
    FROM "propfit"."ptbwa_skp"
    WHERE NOT (year = '2024' AND month = '12' AND day = '31')   /* 깨진 .tmp 파티션만 제외 */
      AND CAST(id_type AS VARCHAR) = '2'
      AND ad_id IS NOT NULL AND trim(CAST(ad_id AS VARCHAR)) <> ''
),
segments_latest1 AS (
    SELECT device_ifa, segments FROM segments_latest WHERE rn = 1
),
candidates AS (
    SELECT DISTINCT b.device_ifa
    FROM "prod-ptbwa-dw"."abi_bid_log_flatten" b
    LEFT JOIN seed_piellaven_ad_id s_piellaven ON b.device_ifa = s_piellaven.device_ifa
    LEFT JOIN seed_discharged_male_ad_id s_discharged_male ON b.device_ifa = s_discharged_male.device_ifa
    LEFT JOIN seed_enlistee_ad_id s_enlistee ON b.device_ifa = s_enlistee.device_ifa
    LEFT JOIN seed_gomsin_ad_id s_gomsin ON b.device_ifa = s_gomsin.device_ifa
    LEFT JOIN seed_je_ad_id s_je ON b.device_ifa = s_je.device_ifa
    LEFT JOIN seed_parents_ad_id s_parents ON b.device_ifa = s_parents.device_ifa
    LEFT JOIN seed_shoplinker_ad_id s_shoplinker ON b.device_ifa = s_shoplinker.device_ifa
    JOIN segments_latest1 seg ON b.device_ifa = seg.device_ifa
    WHERE b.year = '2026'
      AND (b.month IN ('06', '07', '08') OR (b.month = '09' AND CAST(b.day AS INTEGER) <= 25))
      AND b.device_ifa IS NOT NULL AND trim(CAST(b.device_ifa AS VARCHAR)) <> ''
      AND regexp_like(CAST(b.device_ifa AS VARCHAR), '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$')
      AND CAST(b.req_ext_allow_user_data_collection AS VARCHAR) = '1'
      AND (b.device_lmt IS NULL OR CAST(b.device_lmt AS VARCHAR) <> '1')
      AND s_piellaven.device_ifa IS NULL
      AND s_discharged_male.device_ifa IS NULL
      AND s_enlistee.device_ifa IS NULL
      AND s_gomsin.device_ifa IS NULL
      AND s_je.device_ifa IS NULL
      AND s_parents.device_ifa IS NULL
      AND s_shoplinker.device_ifa IS NULL
      AND CAST(b.device_geo_region AS VARCHAR) LIKE 'KR%'
      AND regexp_like(CAST(b.device_osv AS VARCHAR), '^[0-9]+$')
),
seg1 AS (
    SELECT c.device_ifa, split(sl.segments, ';') AS segment_ids
    FROM candidates c
    JOIN segments_latest1 sl ON c.device_ifa = sl.device_ifa
),
matched AS (
    SELECT
        device_ifa,
        array_intersect(segment_ids, split('26455,26456,26457,26458', ',')) AS gender_ids,
        array_intersect(segment_ids, split('10003,10004,10005,10006,10007,10008,10009', ',')) AS age_ids,
        array_intersect(segment_ids, split('10406,10407,10408,10409,10410,10411,10412,10413,10414,10415,10416,10417,10418,11704,11705,11706,11707,11708,11709,11710,11711,11712,11713,11714,11715,11716,39705,39706,39707,39708,39709,39710,39714,39715,39716,39717,39875,39876,39877,39879,39880,39881,39882,39885,10420,10423,22398,27357,27361,27362,27364,27365,27366,27368,27369,20748,27371,27372,27373,27374,27375,27376,27377,27378,27380,27381,27382,27383,27384,27385,27387,27388,27389,27390,27391,27392,27393,27394,27397,27398,27399,27402,27403,27405,27406,27407,27408,27409,27411,27416,27568,27569,27570,27571,27572,27573,27574,27575,27576,27577,27579,27580,27581,27582,27583,27584,27585,27586,27587,27438,27439,27441,27532,27533,10429,10431,10432,27443,27540,27541,27446,27447,27448,27450,27451,27452,27454,27455,27456,27458,27459,27461,27463,27465,27466,27467,27470,10424,10425,10430,10433,27444,27472,27473,27475,27476,27477,10419,10421,10426,10427,10428,27487,27488,27489,27490,27491,27493,27494,27495,27496,27497,27503,27504,27505,10422,27507,27508,27509,27510,27511,27513,27514,27515,27516,27518,27519,27521,27522,27543,27546,27655,27656,27660,27526,27527,27528,27529,27530,27531,27534,27537,27538,27539,27548,27549,27550,27551,27552,27553,27554,27558,27560,27561,27562,27563,27564,27565,27566,53075,53076,53079,53081,53082,53083,53085,53086,53088,53089,53090,53091,53092,53093,53094,53095,53096,53097,53098,53099,53100,53101,53102,53103,53104,53105,53106,53107,53108,53109,53110,53111', ',')) AS residence_ids,
        array_intersect(segment_ids, split('10010,10011,10012,10013,10014,10021,10022,10023,10024,10025,10026,10027,10028,10029,10030,10031,10032,10033,10034,20484,49688,49689,49690,10047,10048,10049,10050,10051,10052,10053,10054,10055,10056,13451,49717,49718,49719,49720,49721,49722,10057,10058,10059,10060,10061,10062,10063,10386,10387,10439,10440,10441,10442,27985,49723,49726,10220,10221,10222,10223,10224,10225,10226,10227,10228,10229,10230,10231,49675,49676,49677,49678,49679,49680,49681,49682,49683,49684,49685,10249,10250,10251,10252,10253,10254,10255,10256,10257,10258,10259,49691,49692,49693,49694,49695,49696,49697,49698,10260,10261,10262,10263,10264,10265,10266,10267,10268,10269,10270,10337,10338,10339,10340,10348,10349,10350,49708,49709,49712,49713,49714,49715,10280,10281,10282,10283,10284,10443,10277,10286,10287,10288,10289,10290,10291,10293,10294,10295,10297,10298,10299,10300,10301,10321,10322,10323,10324,10325,10326,10327,10328,10329,10330,10331,10332,10333,10336,49733,49734,10351,10352,10353,10354,10355,10356,10357,10370,10375,10376,49700,49701,49702,49703,49705,49706,49707,50008,10035,10036,10037,10038,10039,10040,10041,10042,10043,10044,10045,10046,10271,10272,10273,10274,10275,10276,10278,10279,10285,10335,49727,49728,49729,49730,49732,11212,11213,11214,11215,11216,11217,11218,11219,11220,20630,49758,49759,49760,50180,11227,11228,11229,11230,11231,11232,11233,11234,11236,49792,49793,49794,49795,49796,49797,50138,50144,11237,11238,11239,11300,49799,49800,49801,49802,49804,49805,49806,49807,49808,50143,50166,50765,11241,11242,11243,11244,11245,11246,11247,11248,11249,11250,11251,11252,11253,49746,49747,49748,49749,49750,49751,49752,49753,49754,49755,11254,11255,11256,11257,11258,11259,11260,11262,11263,11264,11265,49761,49762,49763,49764,49765,49766,49767,49768,11267,11268,11269,11270,11271,11272,11273,11274,11294,11299,49783,49784,49786,49787,49788,49789,49790,50134,50137,50141,50146,50148,50155,50156,11221,11222,11223,11224,11225,11226,11275,11276,11277,11278,11280,11284,49735,49810,49811,49812,49813,49815,49816,49817,49818,49820,50140,50152,50153,50162,50164,11281,11282,11283,50132,50159,50165,11279,11285,11286,11287,11288,11289,11290,11291,11292,49838,49839,49840,49841,49842,49843,11295,11296,11297,11298,49756,49769,49770,49773,49774,49775,49777,49779,49780,49781,49782,50135,50145,50151,30372,30373,30374,30375,30376,30377,30378,30379,30380,30382,30383,30384,11211,50040,50133,50136,50139,50142,50147,50154,50160,11293,49821,49823,49824,49825,49826,49827,49828,49829,49830,49831,49832,49833,49834,49835,49836', ',')) AS product_ids,
        array_intersect(segment_ids, split('26280,26281,26282,26284,26285,26286,26287,26288,26289,26290,26291,26292,26293,26294,26295,26299,26306,26308,26309,26310,26311,26312,26313,26314,26425,26766,26322,26323,26324,26325,26326,26342,26343,26344,26345,26346,26347,26348,26349,26350,26351,26352,26353,26354,30367,30368,26355,26356,26357,26358,26359,26360,26361,26362,26363,26365,26366,26367,26368,26369,26370,26372,26373,26374,26375,26380,26381,26382,26383,26384,26385,26386,26388,26389,26390,26392,26393,26394,26395,26396,26397,26398,26399,26400,26401,26403,26404,26405,26406,26407,26408,26410,26413,26416,26418,26419,26420,26421,26422,26423,26424,19661,26426,22335,22336,22337,22338,22339,22340,22341,22342,22343,22344,22345,22346,22347,22348,22349,22350,22351,22352,22353,22355,22356,22357,22358,22359,22360,22361,22362,22364,22365,22366,22367,22368,22369,22370,22371,22372,22373,22374,37687,37695,37703,37683,37694,37697,37700,37689,37691,37698,37699,37701,37702,37705,37690,37704,37685,37686,37696,49372,49373,49374,49375,49376,49379,49381,49382,49383,49384,49390,49391,49393,49394,49395,49396,49397,49399,49400,49402,49406,50343,50344,50346', ',')) AS content_ids,
        array_intersect(segment_ids, split('26937,26941,26946,49386,49387,26948,26949,26950,26952,26957,27009,26610,27151,27209,27699,49404,49411,49450,49605,49606,49607,26625,26929,27011,27013,49405,49407,50215,27015,27016,50191,26924,26926,26932,26935,26986,27049,49398,49403,49742,50188,50189,50190,26978,27334,27335,49408,49410,50230,26604,26609,26611,26612,26615,26666,26667,27613,50236,26607,26755,26959,27063,50216,50217,50218,50219,50220,50222,50224,50225,50226,50227,50228,50229,26645,27348,26634,26740,49388,49389,49392,49737,49738,49739,49740,49741,26662,27155,31327,31329,31331,31349,31350,31632,31637,31638,33025,49599,49602,49603,26591,26629,26630,26631,26633,26646,26649,26663,26664,27341,27353,49370,49452,49453,49455,49456,49457,49458,49586,49587,49588,49589,49591,49594,49597,49598,50232,50233,50234', ',')) AS etc_ids
    FROM seg1
),
gender_scored AS (
    SELECT
        device_ifa,
        age_ids, residence_ids, product_ids, content_ids, etc_ids,
        filter(
            transform(gender_ids, x -> CASE x
                WHEN '26455' THEN 1.0    -- 여성(High)
                WHEN '26456' THEN 0.5    -- 여성(Low)
                WHEN '26457' THEN -1.0   -- 남성(High)
                WHEN '26458' THEN -0.5   -- 남성(Low)
                ELSE NULL
            END),
            x -> x IS NOT NULL
        ) AS gender_scores
    FROM matched
)
SELECT
    device_ifa,
    CASE WHEN cardinality(gender_scores) = 0 THEN 0.0
         ELSE reduce(gender_scores, 0.0, (s, x) -> s + x, s -> s) / cardinality(gender_scores)
    END AS gender_score,
    ARRAY_JOIN(age_ids, ';')      AS age_bracket_ids,
    ARRAY_JOIN(residence_ids, ';') AS residence_ids,
    ARRAY_JOIN(product_ids, ';')   AS product_interest_ids,
    ARRAY_JOIN(content_ids, ';')   AS content_interest_ids,
    ARRAY_JOIN(etc_ids, ';')       AS etc_segment_ids
FROM gender_scored;
